#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
openvela 2026 大赛 —— WorkBuddy AI 聊天记录导出工具（单文件，无第三方依赖）

只做一件事：把 WorkBuddy 的会话导出成大赛要求的
logs/<GITHUB_LOGIN>/<date>/<tool>__<sid>.jsonl（schema v1.0，逐事件一行），
tool 字段默认 workbuddy，并重建 manifest.json。
不导出 MiMo / Claude Code / Codex / DSH 等其它工具的日志。

数据来源
--------
~/.workbuddy-ai/projects/<cwd-encoded>/<session-id>.jsonl
  —— 每行一个事件：session-meta / message / reasoning / function_call /
     function_call_result / ai-title / file-history-snapshot。
  —— user 正文被包在 <system-reminder> 里，真实提问在 <user_query> 标签内，本工具会剥壳。
  —— 模型与 token 用量在 providerData.model / providerData.usage。
~/.workbuddy-ai/workbuddy.db（可选，只读）
  —— sessions 表提供标题 / cwd / 模型，作为 jsonl 缺失时的兜底。

典型用法
--------
  py -3 workbuddy_export.py --list                  # 列出 WorkBuddy 会话（不写盘）
  py -3 workbuddy_export.py --all                   # 预览要导出什么（不写盘）
  py -3 workbuddy_export.py --all --confirm         # 导出/刷新（默认覆盖为最新快照）
  py -3 workbuddy_export.py --all --skip-existing --confirm   # 已存在就不动
  py -3 workbuddy_export.py --today --confirm       # 只导今天结束的会话
  py -3 workbuddy_export.py --session <id> --confirm
  py -3 workbuddy_export.py --validate              # 校验 logs 目录
  py -3 workbuddy_export.py --scrub-existing --confirm   # 只对已有 workbuddy 文件脱敏

行为约定
--------
* 默认预览：不加 --confirm 不写任何文件。
* 默认把会话写成最新快照（同一文件覆盖）；--skip-existing 则已存在就跳过。
* 只导出 WorkBuddy：其它工具的日志一概不碰、不覆盖、不删除。
* 工作区闸门：只采 cwd 位于 openvela 工作区（向上找 .repo）内的会话。
* 密钥脱敏：sk-/ghp_/gho_/github_pat_/tp-/Bearer/私钥/api_key=... 等默认替换，并写 redacted_count；
  可在 logs/<login>/redact.json 追加自定义规则。
* 本工具永不执行 git commit/push，只写本地文件。

退出码：0 成功 / 1 校验失败或写入失败 / 2 参数或环境问题
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import sqlite3
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

SCHEMA_VERSION = "1.0"
EXPORTER_VERSION = "1.0.0"

# WorkBuddy 会话写进 jsonl 的 tool 字段
DEFAULT_TOOL_ID = "workbuddy"

# 校验时认可的 tool 取值（含其它工具，便于 --validate-all）
ALLOWED_TOOLS = {
    "workbuddy",
    "opencode",
    "claude-code",
    "codex",
    "kiro",
    "mimocode",
    "mimo-desktop",
    "cursor",
    "deepseekharness",
}
ALLOWED_ROLES = {"user", "assistant", "tool", "system"}

DEFAULT_TEAM_ID = "contest2026_037_TensorFishSpecialActivityDivison"
DEFAULT_LOGIN = "LR-C11"

SCRIPT_DIR = Path(__file__).resolve().parent


def _home() -> Path:
    try:
        return Path.home()
    except Exception:
        pass
    for key in ("USERPROFILE", "HOME"):
        v = os.environ.get(key)
        if v:
            return Path(v)
    drive = os.environ.get("HOMEDRIVE") or ""
    path_ = os.environ.get("HOMEPATH") or ""
    if drive or path_:
        return Path(drive + path_)
    return Path.cwd()


def _env_path(name: str, default: Path) -> Path:
    v = os.environ.get(name)
    return Path(v).expanduser() if v else default


CLAUDE_ENV_FILE = _env_path("CONTEST_ENV_FILE", _home() / ".claude" / "contest-collector.env")
WB_HOME = _env_path("WORKBUDDY_HOME", _home() / ".workbuddy-ai")
WB_PROJECTS = _env_path("WORKBUDDY_PROJECTS", WB_HOME / "projects")
WB_DB = _env_path("WORKBUDDY_DB", WB_HOME / "workbuddy.db")
TOOL_ID = os.environ.get("WORKBUDDY_TOOL_ID", DEFAULT_TOOL_ID)

# --------------------------------------------------------------------------------------
# 基础工具
# --------------------------------------------------------------------------------------


def now_iso() -> str:
    dt = datetime.now(timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (dt.microsecond // 1000)


def ms_to_iso(ms: Any) -> str:
    try:
        ms_int = int(ms)
    except Exception:
        return now_iso()
    dt = datetime.fromtimestamp(ms_int / 1000.0, tz=timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (ms_int % 1000)


def local_date(ts: Optional[str]) -> str:
    if not ts:
        return datetime.now().strftime("%Y-%m-%d")
    try:
        dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        return dt.astimezone().strftime("%Y-%m-%d")
    except Exception:
        return datetime.now().strftime("%Y-%m-%d")


def parse_ts(ts: Optional[str]) -> Optional[datetime]:
    if not ts:
        return None
    try:
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
    except Exception:
        return None


def is_under(path_str: str, root_str: str) -> bool:
    if not path_str:
        return False
    try:
        p = os.path.normcase(os.path.normpath(path_str)).rstrip("\\/")
        r = os.path.normcase(os.path.normpath(root_str)).rstrip("\\/")
    except Exception:
        return False
    return p == r or p.startswith(r + os.sep)


def find_workspace(start: Path) -> Path:
    """向上找 .repo（openvela 工作区标识）；找不到就返回起始目录。"""
    cur = start.resolve()
    for cand in [cur] + list(cur.parents):
        try:
            if (cand / ".repo").exists():
                return cand
        except Exception:
            continue
    return cur


def load_identity(env_file: Path) -> Tuple[str, str]:
    team_id, login = DEFAULT_TEAM_ID, DEFAULT_LOGIN
    try:
        if env_file.is_file():
            for line in env_file.read_text(encoding="utf-8", errors="replace").splitlines():
                line = line.strip()
                if line.startswith("TEAM_ID="):
                    v = line.split("=", 1)[1].strip().strip('"').strip("'")
                    if v:
                        team_id = v
                elif line.startswith("GITHUB_LOGIN="):
                    v = line.split("=", 1)[1].strip().strip('"').strip("'")
                    if v:
                        login = v
    except Exception:
        pass
    return team_id, login


def clip(text: str, limit: int) -> str:
    if limit and limit > 0 and len(text) > limit:
        return text[:limit] + "\n...<truncated %d chars>" % (len(text) - limit)
    return text


# --------------------------------------------------------------------------------------
# 脱敏
# --------------------------------------------------------------------------------------

DEFAULT_REDACTION: List[Tuple[str, str]] = [
    (r"sk-[A-Za-z0-9_\-]{20,}", "sk-***REDACTED***"),
    (r"gh[pous]_[A-Za-z0-9]{20,}", "gh*_***REDACTED***"),
    (r"github_pat_[A-Za-z0-9_]{20,}", "github_pat_***REDACTED***"),
    (r"tp-[A-Za-z0-9]{20,}", "tp-***REDACTED***"),
    (r"xai-[A-Za-z0-9]{20,}", "xai-***REDACTED***"),
    (r"AKIA[0-9A-Z]{16}", "AKIA***REDACTED***"),
    (r"(?i)bearer\s+[A-Za-z0-9._\-+/=]{16,}", "Bearer ***REDACTED***"),
    (
        r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----",
        "***REDACTED PRIVATE KEY***",
    ),
    (
        r"(?i)((?:api[_-]?key|access[_-]?token|client[_-]?secret|password|passwd|secret)\s*[:=]\s*[\"']?)"
        r"([A-Za-z0-9._\-]{6,})",
        r"\1***REDACTED***",
    ),
]


class Redactor:
    def __init__(self, rules: List[Tuple[str, str]], enabled: bool = True) -> None:
        self.enabled = enabled
        self.rules = [(re.compile(pat), rep) for pat, rep in rules]

    def text(self, s: str) -> Tuple[str, int]:
        if not self.enabled or not s:
            return s, 0
        total = 0
        out = s
        for rx, rep in self.rules:
            out, n = rx.subn(rep, out)
            total += n
        return out, total

    def value(self, v: Any) -> Tuple[Any, int]:
        if not self.enabled:
            return v, 0
        if isinstance(v, str):
            return self.text(v)
        if isinstance(v, list):
            total = 0
            arr = []
            for item in v:
                nv, n = self.value(item)
                arr.append(nv)
                total += n
            return arr, total
        if isinstance(v, dict):
            total = 0
            d: Dict[str, Any] = {}
            for k, item in v.items():
                nv, n = self.value(item)
                d[k] = nv
                total += n
            return d, total
        return v, 0


def load_redaction_rules(member_dir: Path) -> List[Tuple[str, str]]:
    rules = list(DEFAULT_REDACTION)
    custom = member_dir / "redact.json"
    try:
        if custom.is_file():
            data = json.loads(custom.read_text(encoding="utf-8"))
            items = data.get("rules", data) if isinstance(data, dict) else data
            for r in items:
                if isinstance(r, dict) and r.get("pattern"):
                    rules.append((str(r["pattern"]), str(r.get("replacement", "***REDACTED***"))))
    except Exception:
        pass
    return rules


# --------------------------------------------------------------------------------------
# 会话模型
# --------------------------------------------------------------------------------------


class Session:
    def __init__(
        self,
        sid: str,
        tool: str,
        cwd: str,
        title: str,
        events: List[Dict[str, Any]],
        raw_count: int = 0,
        source: Optional[Path] = None,
    ) -> None:
        self.sid = sid
        self.tool = tool
        self.cwd = cwd
        self.title = title
        self.events = events
        self.raw_count = raw_count
        self.source = source
        self.first_ts = next((e["ts"] for e in events if e.get("ts")), None)
        self.last_ts = next((e["ts"] for e in reversed(events) if e.get("ts")), None)

    def date(self, mode: str) -> str:
        return local_date(self.last_ts if mode == "last" else self.first_ts)


# --------------------------------------------------------------------------------------
# 来源：WorkBuddy 会话  —— tool id: workbuddy
#   存储：~/.workbuddy-ai/projects/<cwd-encoded>/<session-id>.jsonl
#   事件：session-meta / message / reasoning / function_call / function_call_result / ai-title
# --------------------------------------------------------------------------------------

# <system-reminder ...> ... </system-reminder>（含 user-context / message-queue 等注入块）
SR_RE = re.compile(r"<system-reminder\b[^>]*>[\s\S]*?</system-reminder>", re.I)
# 真实提问在 <user_query> 里；message-queue 的追问也被这层包住
UQ_RE = re.compile(r"<user_query>([\s\S]*?)</user_query>", re.I)

TEXT_BLOCK_TYPES = {"input_text", "output_text", "text"}
IMAGE_BLOCK_TYPES = {"input_image", "image", "image_url"}


def extract_user_text(raw: str) -> str:
    """剥掉 system-reminder 注入，取出用户真正说的话。"""
    if not raw:
        return ""
    queries = [m.group(1).strip() for m in UQ_RE.finditer(raw)]
    queries = [q for q in queries if q]
    if queries:
        return "\n\n".join(queries)
    return SR_RE.sub("", raw).strip()


def join_text_blocks(content: Any, is_user: bool) -> str:
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    parts: List[str] = []
    for blk in content:
        if not isinstance(blk, dict):
            continue
        btype = str(blk.get("type") or "")
        if btype in TEXT_BLOCK_TYPES:
            text = blk.get("text")
            if isinstance(text, str) and text.strip():
                parts.append(text)
        elif btype in IMAGE_BLOCK_TYPES:
            parts.append("[image]")
        elif btype == "tool_result":
            pass  # 工具结果走 function_call_result 事件
    text = "\n".join(parts)
    return extract_user_text(text) if is_user else text.strip()


def reasoning_text(row: Dict[str, Any]) -> str:
    parts: List[str] = []
    for key in ("rawContent", "content"):
        blocks = row.get(key)
        if isinstance(blocks, str) and blocks.strip():
            parts.append(blocks)
            continue
        if not isinstance(blocks, list):
            continue
        for blk in blocks:
            if not isinstance(blk, dict):
                continue
            if str(blk.get("type") or "") in ("reasoning_text", "text", "summary_text"):
                text = blk.get("text")
                if isinstance(text, str) and text.strip():
                    parts.append(text)
    return "\n".join(parts).strip()


def parse_arguments(raw: Any) -> Any:
    if raw is None:
        return None
    if isinstance(raw, (dict, list)):
        return raw
    s = str(raw)
    try:
        return json.loads(s)
    except Exception:
        return s


def flatten_output(out: Any) -> Optional[str]:
    if out is None:
        return None
    if isinstance(out, str):
        return out
    if isinstance(out, dict):
        otype = str(out.get("type") or "")
        if otype in ("text", "output_text", "input_text") or isinstance(out.get("text"), str):
            text = out.get("text")
            return text if isinstance(text, str) else json.dumps(out, ensure_ascii=False)
        if otype in IMAGE_BLOCK_TYPES:
            return "[image]"
        if otype == "error":
            msg = out.get("message") or out.get("error")
            return str(msg) if msg else json.dumps(out, ensure_ascii=False)
        return json.dumps(out, ensure_ascii=False)
    if isinstance(out, list):
        parts = []
        for item in out:
            v = flatten_output(item)
            if v:
                parts.append(v)
        return "\n".join(parts) if parts else None
    return str(out)


def build_workbuddy_events(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """把 WorkBuddy 原始事件行转成统一的日志事件（保持文件内的追加顺序）。"""
    events: List[Dict[str, Any]] = []
    pending: Dict[str, Dict[str, Any]] = {}
    step_meta: Dict[str, Dict[str, Any]] = {}

    for row in rows:
        if not isinstance(row, dict):
            continue
        etype = row.get("type")
        pd = row.get("providerData") or {}
        ts = ms_to_iso(row.get("timestamp"))
        msg_id = str(pd.get("messageId") or "")
        model = str(pd.get("model") or "")
        usage = pd.get("usage") or {}

        if msg_id:
            meta = step_meta.setdefault(msg_id, {})
            if model and not meta.get("model"):
                meta["model"] = model
            if isinstance(usage, dict):
                if isinstance(usage.get("inputTokens"), int):
                    meta["tokens_in"] = usage["inputTokens"]
                if isinstance(usage.get("outputTokens"), int):
                    meta["tokens_out"] = usage["outputTokens"]
            if not meta.get("model"):
                raw_usage = pd.get("rawUsage") or {}
                if isinstance(raw_usage, dict):
                    if isinstance(raw_usage.get("prompt_tokens"), int):
                        meta.setdefault("tokens_in", raw_usage["prompt_tokens"])
                    if isinstance(raw_usage.get("completion_tokens"), int):
                        meta.setdefault("tokens_out", raw_usage["completion_tokens"])

        if etype == "message":
            role = str(row.get("role") or "")
            if role == "user":
                text = join_text_blocks(row.get("content"), is_user=True)
                if text.strip():
                    events.append({"ts": ts, "role": "user", "text": text, "_msg": ""})
            elif role == "assistant":
                text = join_text_blocks(row.get("content"), is_user=False)
                if text.strip():
                    events.append({"ts": ts, "role": "assistant", "text": text, "_msg": msg_id})

        elif etype == "reasoning":
            text = reasoning_text(row)
            if text:
                events.append({"ts": ts, "role": "assistant", "thinking": text, "_msg": msg_id})

        elif etype == "function_call":
            call_id = str(row.get("callId") or "")
            ev: Dict[str, Any] = {
                "ts": ts,
                "role": "tool",
                "tool_name": str(row.get("name") or "unknown"),
                "tool_call_id": call_id,
                "input": parse_arguments(row.get("arguments")),
                "output": None,
                "_msg": msg_id,
            }
            events.append(ev)
            if call_id:
                pending[call_id] = ev

        elif etype == "function_call_result":
            call_id = str(row.get("callId") or "")
            text = flatten_output(row.get("output"))
            status = str(row.get("status") or "")
            ev = pending.pop(call_id, None) if call_id else None
            if ev is not None:
                ev["output"] = text
                if status and status not in ("completed", "success", "ok"):
                    ev["is_error"] = True
            else:
                item: Dict[str, Any] = {
                    "ts": ts,
                    "role": "tool",
                    "tool_name": str(row.get("name") or "<result>"),
                    "tool_call_id": call_id,
                    "input": None,
                    "output": text,
                    "_msg": "",
                }
                if status and status not in ("completed", "success", "ok"):
                    item["is_error"] = True
                events.append(item)

    # 每个 step 的首个事件挂上模型与 token 用量（WorkBuddy 把 usage 记在该 step 的某个事件上）
    applied = set()
    for ev in events:
        mid = ev.get("_msg") or ""
        ev.pop("_msg", None)
        if not mid or mid in applied:
            continue
        meta = step_meta.get(mid) or {}
        applied.add(mid)
        if meta.get("model"):
            ev["model"] = meta["model"]
        if isinstance(meta.get("tokens_in"), int):
            ev["tokens_in"] = meta["tokens_in"]
        if isinstance(meta.get("tokens_out"), int):
            ev["tokens_out"] = meta["tokens_out"]

    return events


def _load_db_meta() -> Dict[str, Dict[str, Any]]:
    """从 workbuddy.db 读会话标题/cwd/模型；失败则返回空表（不影响导出）。"""
    meta: Dict[str, Dict[str, Any]] = {}
    if not WB_DB.is_file():
        return meta
    try:
        uri = "file:%s?mode=ro" % WB_DB.as_posix().replace("?", "%3f").replace("#", "%23")
        conn = sqlite3.connect(uri, uri=True, timeout=2.0)
        try:
            for sid, title, cwd, model in conn.execute(
                "SELECT id, title, cwd, model FROM sessions"
            ):
                meta[str(sid)] = {"title": title or "", "cwd": cwd or "", "model": model or ""}
        finally:
            conn.close()
    except Exception:
        return {}
    return meta


def load_workbuddy_sessions(
    workspace: Path, allow_outside: bool, tool_id: str = TOOL_ID
) -> Tuple[List[Session], int, List[str]]:
    notes: List[str] = []
    if not WB_PROJECTS.is_dir():
        return [], 0, ["未找到 WorkBuddy 会话目录：%s" % WB_PROJECTS]

    files = sorted(
        f
        for f in WB_PROJECTS.glob("*/*.jsonl")
        if not f.name.endswith(".file-rollback.ndjson")
    )
    if not files:
        return [], 0, notes

    db_meta = _load_db_meta()
    sessions: List[Session] = []
    skipped = 0
    failed = 0

    for f in files:
        sid = f.stem
        cwd = ""
        title = ""
        rows: List[Dict[str, Any]] = []
        try:
            with f.open("r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                    except Exception:
                        continue
                    if not isinstance(obj, dict):
                        continue
                    rows.append(obj)
                    if not cwd and obj.get("cwd"):
                        cwd = str(obj["cwd"])
                    if obj.get("type") == "ai-title" and obj.get("aiTitle"):
                        title = str(obj["aiTitle"])
                    if obj.get("type") == "session-meta":
                        sid = str(obj.get("sessionId") or sid)
        except Exception:
            failed += 1
            continue

        if not rows:
            continue
        meta = db_meta.get(sid) or {}
        if not cwd:
            cwd = str(meta.get("cwd") or "")
        if not title:
            title = str(meta.get("title") or "")

        if not allow_outside and cwd and not is_under(cwd, str(workspace)):
            skipped += 1
            continue

        events = build_workbuddy_events(rows)
        if not events:
            continue
        sessions.append(
            Session(sid, tool_id, cwd, title, events, raw_count=len(rows), source=f)
        )

    if failed:
        notes.append("有 %d 个 WorkBuddy 会话文件读取失败（可能正在写入），已跳过。" % failed)
    return sessions, skipped, notes


