def event_line(
    sess: Session,
    seq: int,
    ev: Dict[str, Any],
    team_id: str,
    login: str,
    redactor: Redactor,
    max_io: int = 0,
) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "session_id": sess.sid,
        "team_id": team_id,
        "github_login": login,
        "tool": sess.tool,
        "seq": seq,
    }
    payload = dict(ev)
    if max_io:
        if isinstance(payload.get("output"), str):
            payload["output"] = clip(payload["output"], max_io)
        if payload.get("input") is not None and not isinstance(payload["input"], str):
            payload["input"] = clip(
                json.dumps(payload["input"], ensure_ascii=False), max_io
            )
    out.update(payload)
    out, count = redactor.value(out)
    if count:
        out["redacted_count"] = count
    return out


def write_session(
    sess: Session,
    out_root: Path,
    team_id: str,
    login: str,
    date_mode: str,
    redactor: Redactor,
    overwrite: bool,
    max_io: int = 0,
) -> Optional[Dict[str, Any]]:
    date = sess.date(date_mode)
    target = out_root / date / ("%s__%s.jsonl" % (sess.tool, sess.sid))
    if target.exists() and not overwrite:
        return None
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_suffix(".jsonl.tmp")
    total_redacted = 0
    with tmp.open("w", encoding="utf-8", newline="\n") as fh:
        for i, ev in enumerate(sess.events):
            line = event_line(sess, i, ev, team_id, login, redactor, max_io)
            total_redacted += int(line.get("redacted_count", 0) or 0)
            fh.write(json.dumps(line, ensure_ascii=False) + "\n")
    tmp.replace(target)
    return {
        "path": target,
        "date": date,
        "event_count": len(sess.events),
        "redacted": total_redacted,
        "raw_count": sess.raw_count,
        "session": sess,
    }


DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _scan_jsonl(path: Path, login: str) -> Dict[str, Any]:
    """扫一个 jsonl，生成 manifest 条目。"""
    count = 0
    first_ts = last_ts = None
    sid = tool = model = None
    redacted_total = 0
    seq_ok = True
    prev_seq = -1
    with path.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            count += 1
            try:
                ev = json.loads(line)
            except Exception:
                continue
            if first_ts is None:
                first_ts = ev.get("ts")
                sid = ev.get("session_id")
                tool = ev.get("tool")
            last_ts = ev.get("ts") or last_ts
            if not model and ev.get("model"):
                model = ev.get("model")
            redacted_total += int(ev.get("redacted_count", 0) or 0)
            seq = ev.get("seq")
            if not isinstance(seq, int) or seq != prev_seq + 1:
                seq_ok = False
            else:
                prev_seq = seq
    entry: Dict[str, Any] = {
        "session_id": sid or path.stem,
        "tool": tool or (path.name.split("__", 1)[0] if "__" in path.name else ""),
        "started_at": first_ts or now_iso(),
        "last_event_at": last_ts or first_ts or now_iso(),
        "event_count": count,
        "file_path": "logs/%s/%s/%s" % (login, path.parent.name, path.name),
        "collection_mode": "cli",
        "health": "ok" if seq_ok else "warn",
    }
    if model:
        entry["model"] = model
    if redacted_total:
        entry["redacted_count_total"] = redacted_total
    return entry


def rebuild_manifest(out_root: Path, team_id: str, login: str, tool_id: str = TOOL_ID) -> Dict[str, Any]:
    """重建 manifest.json：本工具的文件重新扫描；其它工具的条目原样保留。"""
    manifest_path = out_root / "manifest.json"
    old: Dict[str, Any] = {}
    try:
        if manifest_path.is_file():
            old = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        old = {}
    old_by_path: Dict[str, Dict[str, Any]] = {}
    for e in old.get("sessions") or []:
        if isinstance(e, dict) and e.get("file_path"):
            old_by_path[str(e["file_path"])] = e

    entries: List[Dict[str, Any]] = []
    others = 0
    for f in sorted(out_root.glob("*/*.jsonl")):
        date_dir = f.parent.name
        if not DATE_RE.match(date_dir):
            continue
        name_tool = f.name.split("__", 1)[0] if "__" in f.name else ""
        rel = "logs/%s/%s/%s" % (login, date_dir, f.name)
        if name_tool != tool_id:
            others += 1
            prev = old_by_path.get(rel)
            if prev is not None:
                entries.append(prev)
                continue
        try:
            entries.append(_scan_jsonl(f, login))
        except Exception:
            continue

    entries.sort(key=lambda e: str(e.get("started_at") or ""))
    manifest = {
        "schema_version": SCHEMA_VERSION,
        "team_id": team_id,
        "github_login": login,
        "generator": "workbuddy-exporter@%s" % EXPORTER_VERSION,
        "updated_at": now_iso(),
        "sessions": entries,
    }
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    if others:
        print("[提示] logs 下还有 %d 个其它工具的日志文件，本脚本不改动它们，manifest 条目原样保留。" % others)
    return manifest


