# 校验
# --------------------------------------------------------------------------------------


class Report:
    def __init__(self) -> None:
        self.errors: List[str] = []
        self.warnings: List[str] = []
        self.files = 0
        self.events = 0

    def err(self, msg: str) -> None:
        self.errors.append(msg)

    def warn(self, msg: str) -> None:
        self.warnings.append(msg)

    def dump(self) -> None:
        for e in self.errors[:300]:
            print("  [FAIL] " + e)
        if len(self.errors) > 300:
            print("  [FAIL] ...共 %d 条错误（仅显示前 300 条）" % len(self.errors))
        for w in self.warnings[:60]:
            print("  [WARN] " + w)
        if len(self.warnings) > 60:
            print("  [WARN] ...共 %d 条警告（仅显示前 60 条）" % len(self.warnings))


def validate_logs(
    out_root: Path,
    team_id: str,
    login: str,
    only_files: Optional[List[Path]] = None,
    partial: bool = False,
) -> Report:
    rep = Report()
    if not out_root.is_dir():
        rep.err("logs 目录不存在：%s" % out_root)
        return rep
    files = sorted(only_files) if only_files is not None else sorted(out_root.glob("*/*.jsonl"))
    if not files:
        rep.err("logs/%s 下没有任何 .jsonl" % login)
    for f in files:
        if not DATE_RE.match(f.parent.name):
            rep.warn("目录名不是日期：%s" % f)
        rep.files += 1
        seq = -1
        group = (None, None, None)
        fold = {"shown": 0, "hidden": 0}

        def add_err(msg: str) -> None:
            if fold["shown"] < 6:
                rep.err(msg)
                fold["shown"] += 1
            else:
                fold["hidden"] += 1

        with f.open("r", encoding="utf-8", errors="replace") as fh:
            for lineno, line in enumerate(fh, 1):
                line = line.strip()
                if not line:
                    continue
                rep.events += 1
                try:
                    ev = json.loads(line)
                except Exception:
                    add_err("%s:%d JSON 解析失败" % (f.name, lineno))
                    continue
                for key in ("schema_version", "session_id", "team_id", "github_login", "tool", "ts", "role", "seq"):
                    if key not in ev:
                        add_err("%s:%d 缺少字段 %s" % (f.name, lineno, key))
                if ev.get("schema_version") != SCHEMA_VERSION:
                    add_err("%s:%d schema_version 不是 1.0" % (f.name, lineno))
                if ev.get("tool") not in ALLOWED_TOOLS:
                    add_err("%s:%d tool 非法：%r" % (f.name, lineno, ev.get("tool")))
                if ev.get("role") not in ALLOWED_ROLES:
                    add_err("%s:%d role 非法：%r" % (f.name, lineno, ev.get("role")))
                if ev.get("team_id") != team_id:
                    rep.warn("%s:%d team_id=%r（期望 %r）" % (f.name, lineno, ev.get("team_id"), team_id))
                if ev.get("github_login") != login:
                    rep.warn("%s:%d github_login=%r（期望 %r）" % (f.name, lineno, ev.get("github_login"), login))
                if parse_ts(ev.get("ts")) is None:
                    add_err("%s:%d ts 不是合法 ISO8601" % (f.name, lineno))
                cur = ev.get("seq")
                if seq == -1 and isinstance(cur, int) and cur > 0:
                    rep.warn("%s 是续写快照，seq 从 %d 开始" % (f.name, cur))
                    seq = cur - 1
                if not isinstance(cur, int) or cur != seq + 1:
                    add_err("%s:%d seq 断档（期望 %d，实际 %r）" % (f.name, lineno, seq + 1, cur))
                seq = cur if isinstance(cur, int) else seq
                if ev.get("role") == "tool":
                    if not ev.get("tool_name"):
                        add_err("%s:%d role=tool 缺少 tool_name" % (f.name, lineno))
                    if not ev.get("tool_call_id"):
                        rep.warn("%s:%d role=tool 缺少 tool_call_id" % (f.name, lineno))
                cur_group = (ev.get("session_id"), ev.get("tool"), ev.get("team_id"))
                if group[0] is None:
                    group = cur_group
                elif cur_group != group:
                    add_err("%s:%d 同一文件内 session/tool/team 不一致" % (f.name, lineno))
        if fold["hidden"]:
            rep.err("%s 另有 %d 条同类问题已折叠（修完前面几条再看）" % (f.name, fold["hidden"]))

    manifest_path = out_root / "manifest.json"
    if not manifest_path.is_file():
        rep.err("缺少 manifest.json：%s" % manifest_path)
    else:
        try:
            man = json.loads(manifest_path.read_text(encoding="utf-8"))
            for key in ("schema_version", "team_id", "github_login", "sessions"):
                if key not in man:
                    rep.err("manifest.json 缺少字段 %s" % key)
            if man.get("schema_version") not in (SCHEMA_VERSION, None):
                rep.warn("manifest.schema_version=%r" % man.get("schema_version"))
            listed = set()
            for e in man.get("sessions") or []:
                fp = str(e.get("file_path") or "")
                listed.add(fp.rsplit("/", 1)[-1])
                if not re.match(r"^logs/[A-Za-z0-9][A-Za-z0-9-]{0,38}/\d{4}-\d{2}-\d{2}/.+\.jsonl$", fp):
                    rep.err("manifest file_path 不合规：%r" % fp)
                rel = fp.split("/", 2)[2] if fp.startswith("logs/") and fp.count("/") >= 3 else ""
                local = out_root / rel.replace("/", os.sep) if rel else None
                if local is not None and not local.is_file():
                    rep.err("manifest 引用的文件不存在：%s" % fp)
            if not partial:
                actual = {f.name for f in files}
                missing = actual - listed
                if missing:
                    rep.warn("有 %d 个 .jsonl 未登记进 manifest（例如 %s）" % (len(missing), sorted(missing)[0]))
        except Exception as exc:
            rep.err("manifest.json 读取失败：%s" % exc)
    return rep


