def collect_existing_sids(out_root: Path, tool_id: str) -> Dict[str, List[Path]]:
    found: Dict[str, List[Path]] = {}
    try:
        for f in out_root.glob("*/%s__*.jsonl" % tool_id):
            sid = f.stem.split("__", 1)[1]
            found.setdefault(sid, []).append(f)
    except Exception:
        pass
    return found


def print_table(sessions: List[Session], existing: Dict[str, List[Path]]) -> None:
    print("%-42s %-10s %-10s %6s  %s" % ("session_id", "first", "last", "events", "title"))
    print("-" * 110)
    for s in sorted(sessions, key=lambda x: (x.last_ts or "")):
        mark = "*" if s.sid in existing else " "
        print(
            "%-42s %-10s %-10s %6d %s %s"
            % (s.sid[:42], local_date(s.first_ts), local_date(s.last_ts), len(s.events), mark, (s.title or "")[:44])
        )


def select(
    sessions: List[Session],
    session_ids: List[str],
    today: bool,
    since: Optional[str],
    all_flag: bool,
    latest: bool,
) -> List[Session]:
    chosen = sessions
    if session_ids:
        wanted = set(session_ids)
        chosen = [s for s in chosen if s.sid in wanted or any(s.sid.startswith(w) for w in wanted)]
    if today:
        today_str = datetime.now().strftime("%Y-%m-%d")
        chosen = [s for s in chosen if local_date(s.last_ts) == today_str]
    if since:
        cutoff = parse_ts(since + "T00:00:00+00:00") if len(since) == 10 else parse_ts(since)
        if cutoff is not None:
            picked = []
            for s in chosen:
                dt = parse_ts(s.last_ts)
                if dt is not None and dt >= cutoff:
                    picked.append(s)
            chosen = picked
    if latest:
        chosen = sorted(chosen, key=lambda s: s.last_ts or "")[-1:]
    return sorted(chosen, key=lambda s: s.last_ts or "")


def sync_to_repo(out_root: Path, login: str, repo: Path, confirm: bool) -> None:
    dst = repo / "logs" / login
    print("\n把 logs 同步进比赛仓：%s" % dst)
    if not confirm:
        print("  （预览）将覆盖 %s 下的同名文件" % dst)
        return
    dst.mkdir(parents=True, exist_ok=True)
    if (out_root / "manifest.json").is_file():
        shutil.copy2(str(out_root / "manifest.json"), str(dst / "manifest.json"))
    for src_dir in sorted(out_root.iterdir()):
        if not src_dir.is_dir() or not DATE_RE.match(src_dir.name):
            continue
        target_dir = dst / src_dir.name
        target_dir.mkdir(parents=True, exist_ok=True)
        for src_file in src_dir.glob("*.jsonl"):
            shutil.copy2(str(src_file), str(target_dir / src_file.name))
    print("  已同步。接下来在比赛仓执行：")
    print("    git add logs/")
    print('    git commit -s -m "logs: sync AI sessions"')
    print("    git push")


def cmd_scrub(out_root: Path, tool_id: str, redactor: Redactor, confirm: bool) -> int:
    total = 0
    files = 0
    targets = sorted(out_root.glob("*/%s__*.jsonl" % tool_id))
    for f in targets:
        try:
            lines = f.read_text(encoding="utf-8", errors="replace").splitlines()
        except Exception:
            continue
        changed = False
        out_lines: List[str] = []
        for line in lines:
            if not line.strip():
                continue
            try:
                ev = json.loads(line)
            except Exception:
                out_lines.append(line)
                continue
            nv, cnt = redactor.value(ev)
            if cnt:
                nv["redacted_count"] = int(nv.get("redacted_count", 0)) + cnt
                total += cnt
                changed = True
            out_lines.append(json.dumps(nv, ensure_ascii=False))
        if changed:
            files += 1
            if confirm:
                f.write_text("\n".join(out_lines) + "\n", encoding="utf-8")
    print("脱敏：%d 个文件、共 %d 处%s" % (files, total, "" if confirm else "（预览，未写盘）"))
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")  # type: ignore[attr-defined]
    except Exception:
        pass

    ap = argparse.ArgumentParser(
        description="只导出 WorkBuddy 聊天记录到 logs/<login>/ 下（默认预览，--confirm 才写盘）",
        formatter_class=argparse.RawTextHelpFormatter,
    )
    ap.add_argument("--list", action="store_true", help="只列出候选会话，不写盘")
    ap.add_argument("--session", action="append", default=[], help="指定 session_id（可重复，支持前缀）")
    ap.add_argument("--latest", action="store_true", help="只导出最近一个会话")
    ap.add_argument("--today", action="store_true", help="只导出今天结束的会话")
    ap.add_argument("--since", help="只导出该日期（YYYY-MM-DD）之后结束的会话")
    ap.add_argument("--all", action="store_true", help="导出工作区内全部会话")
    ap.add_argument("--confirm", action="store_true", help="真正写入；缺省只预览")
    ap.add_argument("--skip-existing", action="store_true", help="已存在同会话文件时跳过（默认刷新为最新快照）")
    ap.add_argument("--rebuild-manifest", action="store_true", help="即使没有新会话也重建 manifest.json")
    ap.add_argument("--tool-id", default=TOOL_ID, help="写进 jsonl 的 tool 字段（默认 workbuddy）")
    ap.add_argument("--out", help="输出根目录（默认：本脚本目录/logs/<login>）")
    ap.add_argument("--repo", help="比赛仓路径（用于 --sync-repo）")
    ap.add_argument("--sync-repo", action="store_true", help="导出后把 logs 同步进比赛仓（配合 --confirm）")
    ap.add_argument("--workspace", help="openvela 工作区根目录（默认：向上找 .repo，找不到则用脚本目录）")
    ap.add_argument("--allow-outside", action="store_true", help="允许导出工作区之外的会话（不建议）")
    ap.add_argument("--team-id", help="覆盖 TEAM_ID")
    ap.add_argument("--login", help="覆盖 GITHUB_LOGIN")
    ap.add_argument("--env-file", help="contest-collector.env 路径")
    ap.add_argument("--date-mode", choices=["last", "start"], default="last", help="按会话最后/首个事件日期分目录")
    ap.add_argument("--max-io", type=int, default=0, help="单条工具出入参最大字符数，0=不截断")
    ap.add_argument("--no-redact", action="store_true", help="关闭密钥脱敏（不建议）")
    ap.add_argument("--validate", action="store_true", help="校验 WorkBuddy 日志与 manifest")
    ap.add_argument("--validate-all", action="store_true", help="连同 logs 下其它工具的历史文件一起校验")
    ap.add_argument("--scrub-existing", action="store_true", help="只对 logs 下已有的 workbuddy 文件做脱敏")
    ap.add_argument("--no-auto-validate", action="store_true", help="写盘后不做自动校验")
    args = ap.parse_args(argv)

    env_file = Path(args.env_file).expanduser() if args.env_file else CLAUDE_ENV_FILE
    team_id, login = load_identity(env_file)
    team_id = args.team_id or team_id
    login = args.login or login
    tool_id = args.tool_id

    workspace = Path(args.workspace).expanduser() if args.workspace else find_workspace(SCRIPT_DIR)
    out_root = Path(args.out).expanduser() if args.out else (SCRIPT_DIR / "logs" / login)
    out_root = out_root.resolve()

    redactor = Redactor(load_redaction_rules(out_root), enabled=not args.no_redact)

    print("=== openvela AI 日志导出（WorkBuddy） ===")
    print("team_id      : %s" % team_id)
    print("github_login : %s" % login)
    print("tool         : %s" % tool_id)
    print("workspace    : %s" % workspace)
    print("会话来源     : %s" % WB_PROJECTS)
    print("输出目录     : %s" % out_root)
    print("")

    if args.validate or args.validate_all:
        if args.validate_all:
            rep = validate_logs(out_root, team_id, login)
            scope = "全部文件"
        else:
            wb_files = sorted(out_root.glob("*/" + tool_id + "__*.jsonl"))
            rep = validate_logs(out_root, team_id, login, only_files=wb_files, partial=True)
            scope = "仅 WorkBuddy 文件（--validate-all 可全量校验）"
        print("校验（%s）：%d 个文件 / %d 条事件" % (scope, rep.files, rep.events))
        rep.dump()
        print("结果：%s" % ("FAIL" if rep.errors else ("WARN" if rep.warnings else "PASS")))
        return 1 if rep.errors else 0

    if args.scrub_existing:
        rc = cmd_scrub(out_root, tool_id, redactor, args.confirm)
        if args.confirm:
            rebuild_manifest(out_root, team_id, login, tool_id)
            print("manifest.json 已重建。")
        return rc

    # ---------- 采集（只采 WorkBuddy） ----------
    sessions, outside_count, notes = load_workbuddy_sessions(workspace, args.allow_outside, tool_id)
    for n in notes:
        print("[注意] " + n)

    # 去重（同 session_id 只留事件最多的一个）
    best: Dict[str, Session] = {}
    for s in sessions:
        if s.sid not in best or len(s.events) > len(best[s.sid].events):
            best[s.sid] = s
    sessions = list(best.values())

    if args.list:
        existing = collect_existing_sids(out_root, tool_id)
        print("\n候选会话（* = logs 里已有该会话文件）：")
        print_table(sessions, existing)
        if outside_count:
            print("\n另有 %d 个会话在工作区之外，已按规则排除（--allow-outside 可放开）。" % outside_count)
        return 0

    has_filter = bool(args.session or args.today or args.since or args.all or args.latest)
    chosen = select(sessions, args.session, args.today, args.since, args.all, args.latest)
    existing_sids = collect_existing_sids(out_root, tool_id)
    if args.skip_existing:
        kept = [s for s in chosen if s.sid in existing_sids]
        chosen = [s for s in chosen if s.sid not in existing_sids]
        if kept:
