        print("请用 --all / --today / --since <date> / --session <id> / --latest 选择要导出的会话，再追加 --confirm。")
        return 0
    if not chosen:
        print("没有匹配的会话。可先用 --list 查看。")
        return 0

    print("\n本次将导出 %d 个会话：" % len(chosen))
    total_events = 0
    for s in chosen:
        total_events += len(s.events)
        print(
            "  %-40s %s  events=%d  -> %s"
            % (s.sid[:40], local_date(s.last_ts), len(s.events), out_root / s.date(args.date_mode) / ("%s__%s.jsonl" % (tool_id, s.sid)))
