    print("合计事件：%d" % total_events)

    if not args.confirm:
        print("\n以上为预览，未写入任何文件。确认无误后追加 --confirm 执行。")
        return 0

    # ---------- 写盘 ----------
    failed = 0
    written = 0
    written_paths: List[Path] = []
    for s in chosen:
        try:
            info = write_session(
                s, out_root, team_id, login, args.date_mode, redactor,
                overwrite=not args.skip_existing, max_io=args.max_io,
            )
            if info is None:
                print("  跳过（已存在）：%s" % s.sid)
                continue
            written += 1
            written_paths.append(info["path"])
            red = ("  redacted=%d" % info["redacted"]) if info["redacted"] else ""
            print("  写入 %s（%d 条）%s" % (info["path"], info["event_count"], red))
        except Exception as exc:
            failed += 1
            print("  [失败] %s：%s" % (s.sid, exc))

    if written > 0 or args.rebuild_manifest:
        manifest = rebuild_manifest(out_root, team_id, login, tool_id)
        print("\nmanifest.json 已重建：%d 个会话记录" % len(manifest.get("sessions") or []))
    else:
        print("\n没有写入新会话，manifest.json 未改动（如需重建加 --rebuild-manifest）。")

    if args.sync_repo:
        repo = Path(args.repo).expanduser() if args.repo else None
        if repo is None:
            cands = sorted(workspace.glob("contest2026_*"))
            repo = cands[0] if cands else None
        if repo is None:
            print("未找到比赛仓（用 --repo 指定），已跳过 --sync-repo。")
        else:
            sync_to_repo(out_root, login, repo, args.confirm)

    if not args.no_auto_validate and written_paths:
