        rep.dump()

    print("\n完成：写入 %d 个会话，失败 %d 个。" % (written, failed))
    print("下一步（在比赛仓根目录）：")
    print("  git add logs/")
    print('  git commit -s -m "logs: sync AI sessions"')
    print("  git push")
